## Code Example

```javascript
// Simple two-period CSP checker with Kleene semantics
function kleeneNot(x) { if(x==='T') return 'F'; if(x==='F') return 'T'; return 'U'; }
function kleeneOr(a,b) { if(a==='T'||b==='T') return 'T'; if(a==='U'||b==='U') return 'U'; return 'F'; }
function kleeneAnd(a,b) { if(a==='F'||b==='F') return 'F'; if(a==='U'||b==='U') return 'U'; return 'T'; }
function kleeneImplies(a,b) { return kleeneOr(kleeneNot(a), b); }

// Check constraints across both periods
function validateConstraints(t0, t1) {
  const withinT0 = [
    kleeneImplies(kleeneOr(t0.C1, t0.C2), t0.C3),
    kleeneOr(kleeneNot(t0.C5), t0.C4),
    kleeneImplies(kleeneAnd(t0.C2, kleeneNot(t0.C3)), kleeneOr(t0.C1, t0.C5))
  ];
  const withinT1 = [
    kleeneImplies(kleeneOr(t1.C1, t1.C2), t1.C3),
    kleeneOr(kleeneNot(t1.C5), t1.C4),
    kleeneImplies(kleeneAnd(t1.C2, kleeneNot(t1.C3)), kleeneOr(t1.C1, t1.C5))
  ];
  const cross = kleeneImplies(kleeneOr(t0.C1, t1.C4), t0.C2);

  return [...withinT0, ...withinT1, cross].every(v => v !== 'F');
}
```

## Why This Is Asked

This question tests the ability to reason with SQL's three-valued logic and NULL propagation, moving beyond standard boolean algebra. It assesses understanding of how NULL behaves in real-world database systems.

## Key Concepts

- **Three-valued logic semantics**: TRUE, FALSE, and UNKNOWN (NULL)
- **Kleene truth tables**:
  - AND: TRUE∧x=x, FALSE∧x=FALSE, NULL∧x=NULL (except NULL∧FALSE=FALSE)
  - OR: TRUE∨x=TRUE, FALSE∨x=x, NULL∨x=NULL (except NULL∨FALSE=NULL)
  - NOT: ¬TRUE=FALSE, ¬FALSE=TRUE, ¬NULL=NULL
- Constraint propagation and backtracking strategies

## Code Example

```python
def evaluate_kleene(expr, env):
    if isinstance(expr, bool):
        return expr
    if expr == 'NULL':
        return None
    op, left, right = expr['op'], expr['left'], expr['right']
    lval = evaluate_kleene(left, env)
    rval = evaluate_kleene(right, env)

    if op == 'AND':
        if lval is False or rval is False:
            return False
        if lval is None or rval is None:
            return None
        return True
    elif op == 'OR':
        if lval is True or rval is True:
            return True
        if lval is None or rval is None:
            return None
        return False
    elif op == 'NOT':
        if lval is None:
            return None
        return not lval
```

